begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
('10000000-0000-4000-8000-000000000001','profiles.member@example.test',now()),
('10000000-0000-4000-8000-000000000002','profiles.admin@example.test',now()),
('10000000-0000-4000-8000-000000000003','profiles.other@example.test',now());
select public.provision_member('10000000-0000-4000-8000-000000000001','Membre','Test');
select public.provision_member('10000000-0000-4000-8000-000000000002','Admin','Test');
select public.provision_member('10000000-0000-4000-8000-000000000003','Autre','Test');
update public.members set role='admin' where email='profiles.admin@example.test';
create temp table profile_fixture as select id,email from public.members where email like 'profiles.%';
grant select on profile_fixture to anon,authenticated;

set local role anon;
select throws_ok($$select public.update_own_profile('A','B','','N2','',false,0,'')$$,'42501',null,'Anonymous profile editing is denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.update_own_profile('Prénom','Nom','0612345678','N2','N3',true,3,'Parking')$$,'Members edit their normal profile fields');
select is((select current_level from public.members),'N2','Level is saved');
select is((select role::text from public.members),'member','Normal edits preserve role');
select is((select email from public.members),'profiles.member@example.test','Normal edits preserve linked email');
select is((select caci_expiry_date from public.members),null::date,'Normal edits preserve CACI');
select is((select usual_passenger_seats from public.members),3,'Optional usual passenger defaults are saved');
select is((select count(*) from public.members),1::bigint,'Normal members still cannot browse the directory');
select throws_ok($$select public.update_own_profile('','','','N2','',false,0,'')$$,'22023',null,'Empty names are rejected');
select throws_ok($$select public.update_own_profile('A','B','','N2','',true,9,'')$$,'22023',null,'Usual seats stay within 1..8');
select throws_ok($$select public.set_member_caci(public.current_member_id(),date '2027-10-02')$$,'42501',null,'Member cannot edit own CACI through RPC');
select throws_ok($$update public.members set caci_expiry_date=date '2027-10-02'$$,'42501',null,'Member cannot edit CACI directly');
select lives_ok($$select public.update_own_profile('A','B','','N2','',false,8,'Ancien')$$,'Members can opt out of usual car defaults');
select is((select usual_passenger_seats from public.members),0,'Opt-out clears seats');
select is((select usual_meeting_point from public.members),'','Opt-out clears meeting defaults');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.set_member_caci(public.current_member_id(),date '2027-10-02')$$,'Admin can edit own CACI');
select lives_ok($$select public.set_member_caci((select id from profile_fixture where email='profiles.member@example.test'),date '2027-12-02')$$,'Admin can edit another member CACI');
select is((select count(*) from public.members),3::bigint,'Admin can read the directory');
select is((select count(*) from public.audit_events where event_type='caci_date_changed' and target_member_id in (select id from profile_fixture)),2::bigint,'CACI mutations are audited');
select lives_ok($$select public.set_member_caci((select id from profile_fixture where email='profiles.member@example.test'))$$,'Admin can clear a missing CACI date');
select throws_ok($$select public.set_member_caci(public.current_member_id(),'infinity'::date)$$,'23514',null,'CACI cannot be infinite');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select is((select caci_expiry_date from public.members),null::date,'The member sees the administrator-maintained date');
reset role;
select is((select first_name from public.members where email='profiles.other@example.test'),'Autre','Ordinary profile edits cannot change another member');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.set_member_caci((select id from profile_fixture where email='profiles.other@example.test'),date '2030-01-01')$$,'42501',null,'Member cannot edit another CACI');
select throws_ok($$select public.set_member_caci_if_current(public.current_member_id(),date '2030-01-01')$$,'42501',null,'Member cannot use guarded CACI write');
select is((select count(*) from public.members where id=(select id from profile_fixture where email='profiles.other@example.test')),0::bigint,'Private other profile is not retrievable');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.set_member_caci_if_current((select id from profile_fixture where email='profiles.member@example.test'),date '2028-01-01',null)$$,'Guarded write handles initially empty date');
select throws_ok($$select public.set_member_caci_if_current((select id from profile_fixture where email='profiles.member@example.test'),date '2029-01-01',null)$$,'PGRST',jsonb_build_object('code','40001','message','CACI_EDIT_CONFLICT','details',null,'hint',null)::text,'Stale editor cannot overwrite a new value');
select is((select caci_expiry_date from public.members where email='profiles.member@example.test'),date '2028-01-01','Conflict preserves server date');
select lives_ok($$select public.set_member_caci_if_current((select id from profile_fixture where email='profiles.member@example.test'),null,date '2028-01-01')$$,'Guarded write can intentionally clear current date');
reset role;
-- Admin profile editing uses an explicit target, a current revision and no
-- general-purpose table UPDATE privilege.
create temp table admin_profile_snapshot as select * from public.members where email='profiles.member@example.test';
grant select on admin_profile_snapshot to authenticated;
set local role anon;
select throws_ok($$select public.update_member_profile_if_current(null,now(),'A','B','','N2','')$$,'42501',null,'Anonymous admin profile editing is denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.update_member_profile_if_current((select id from profile_fixture where email='profiles.other@example.test'),now(),'A','B','','N2','')$$,'42501',null,'Member cannot edit another profile through admin RPC');
select throws_ok($$select public.update_member_profile_if_current(public.current_member_id(),now(),'A','B','','N2','')$$,'42501',null,'Member cannot use admin RPC on self');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.update_member_profile_if_current(id,updated_at,' Nouveau ',' Nom ',' 0612345678 ',' N3 ',' Qualification libre ') from admin_profile_snapshot$$,'Admin edits another profile including free-text levels');
select is((select current_level from public.members where id=(select id from admin_profile_snapshot)),'N3','Admin level change persists');
select is((select preparing_level from public.members where id=(select id from admin_profile_snapshot)),'Qualification libre','Preparing level remains free text');
select is((select first_name from public.members where id=(select id from admin_profile_snapshot)),'Nouveau','Names are trimmed');
select is((select to_jsonb(m)-array['first_name','last_name','phone','current_level','preparing_level','updated_at'] from public.members m where id=(select id from admin_profile_snapshot)),(select to_jsonb(s)-array['first_name','last_name','phone','current_level','preparing_level','updated_at'] from admin_profile_snapshot s),'Admin edit preserves Auth/email, role, access, CACI and car defaults');
select is((select count(*) from public.audit_events where event_type='member_profile_changed' and actor_member_id=public.current_member_id() and target_member_id=(select id from admin_profile_snapshot)),1::bigint,'Admin edit is audited with actor and target');
select throws_ok($$select public.update_member_profile_if_current(id,updated_at-interval '1 second','A','B','','N1','') from admin_profile_snapshot$$,'PGRST',jsonb_build_object('code','40001','message','PROFILE_EDIT_CONFLICT','details',null,'hint',null)::text,'Stale admin editor receives conflict');
select throws_ok($$select public.update_member_profile_if_current(id,null,'A','B','','N1','') from admin_profile_snapshot$$,'PGRST',null,'Missing revision cannot bypass conflict guard');
select is((select current_level from public.members where id=(select id from admin_profile_snapshot)),'N3','Stale edit preserves saved level');
select throws_ok($$select public.update_member_profile_if_current(id,updated_at,' ','B','','N1','') from admin_profile_snapshot$$,'22023',null,'Empty admin-edited name is rejected');
select throws_ok($$select public.update_member_profile_if_current(id,updated_at,'A','B','',repeat('N',41),'') from admin_profile_snapshot$$,'22023',null,'Overlong admin-edited level is rejected');
select throws_ok($$select public.update_member_profile_if_current('99999999-9999-4999-8999-999999999999',now(),'A','B','','N1','')$$,'22023',null,'Unknown target is rejected');
select throws_ok($$update public.members set current_level='N4'$$,'42501',null,'Admins still cannot bypass RPC with direct table update');
select lives_ok($$select public.update_member_profile_if_current(id,updated_at,'Admin','Test','','','') from public.members where id=public.current_member_id()$$,'Admin can edit self and clear optional levels');
reset role;
update public.members set role='president' where email='profiles.admin@example.test';
set local role authenticated;
select lives_ok($$select public.update_member_profile_if_current(id,updated_at,'Nouveau','Nom','','N4','') from public.members where id=(select id from admin_profile_snapshot)$$,'President inherits admin profile editing');
reset role;
update public.members set role='admin', disabled_at=now() where email='profiles.admin@example.test';
set local role authenticated;
select throws_ok($$select public.update_member_profile_if_current(null,now(),'A','B','','N1','')$$,'42501',null,'Disabled administrator cannot edit profiles with an existing JWT');
reset role;
select * from finish();
rollback;
